<?php
declare(strict_types=1);namespace App\Application\Reconciliation;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Domain\Reconciliation\MatchEngine;use App\Models\{PaymentIntentRecord,ReconciliationImport,ReconciliationItem,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class ReconciliationService{public function __construct(private MatchEngine$engine,private AuditWriter$audit,private OutboxWriter$outbox){}public function import(?string$tenant,array$d,User$actor):ReconciliationImport{return DB::transaction(function()use($tenant,$d,$actor){if(ReconciliationImport::where('file_hash',$d['file_hash'])->exists())throw ValidationException::withMessages(['file_hash'=>__('wave4.statement_duplicate')]);$r=ReconciliationImport::create([...$d,'tenant_id'=>$tenant,'status'=>'PROCESSING','total_rows'=>count($d['items']),'uploaded_by'=>$actor->id]);$matched=0;$exceptions=0;foreach($d['items']as$row){$payment=PaymentIntentRecord::where('provider_reference',$row['external_reference'])->when($tenant,fn($q)=>$q->where('tenant_id',$tenant))->first();$decision=$this->engine->decide((int)$row['gross_minor'],(int)($payment?->amount_minor??-1),$d['currency'],$payment?->currency??$d['currency'],(bool)$payment);$decision->status==='MATCHED'?$matched++:$exceptions++;ReconciliationItem::create([...$row,'reconciliation_import_id'=>$r->id,'currency'=>$d['currency'],'status'=>$decision->status,'matched_type'=>$payment?'PAYMENT_INTENT':null,'matched_id'=>$payment?->id,'exception_code'=>$decision->exceptionCode,'raw_data'=>$row]);}unset($r->items);$r->update(['status'=>$exceptions?'COMPLETED_WITH_EXCEPTIONS':'COMPLETED','matched_rows'=>$matched,'exception_rows'=>$exceptions,'completed_at'=>now()]);$this->audit->record('reconciliation.completed','reconciliation_import',$r->id,['matched'=>$matched,'exceptions'=>$exceptions]);return$r->refresh();});}public function resolve(ReconciliationItem$i,array$d,User$actor):ReconciliationItem{if($i->status!=='EXCEPTION')throw ValidationException::withMessages(['status'=>__('wave4.exception_closed')]);$i->update(['status'=>$d['resolution'],'matched_type'=>$d['matched_type']??null,'matched_id'=>$d['matched_id']??null,'resolution_notes'=>$d['notes'],'resolved_by'=>$actor->id,'resolved_at'=>now()]);$this->audit->record('reconciliation.exception.resolved','reconciliation_item',$i->id,['resolution'=>$d['resolution']]);return$i->refresh();}public function approve(ReconciliationImport$r,User$actor):ReconciliationImport{if(!in_array($r->status,['COMPLETED','COMPLETED_WITH_EXCEPTIONS'],true)||$r->items()->where('status','EXCEPTION')->exists())throw ValidationException::withMessages(['status'=>__('wave4.reconciliation_not_approvable')]);if($r->uploaded_by===$actor->id)throw ValidationException::withMessages(['actor'=>__('wave4.maker_checker')]);$r->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$r->items()->where('status','MATCHED')->where('matched_type','PAYMENT_INTENT')->get()->each(function($x){PaymentIntentRecord::whereKey($x->matched_id)->update(['reconciled_at'=>now()]);/* REQ-OBL-001: settle the obligation the reconciled payment pays (idempotent). */try{if($p=PaymentIntentRecord::find($x->matched_id))app(\App\Application\Finance\Obligations\PolicyPremiumObligations::class)->settlePayment($p);}catch(\Throwable$e){report($e);}});$this->outbox->record('reconciliation.approved','reconciliation_import',$r->id,['reconciliation_import_id'=>$r->id]);return$r->refresh();}}
